import sys, os, json, time, datetime, secrets, pathlib, inspect
sys.path.insert(0, '/home/r/dev/minor/stackd/scripts/aws')
import aws_cli
import boto3, botocore, urllib3
from botocore.config import Config
from botocore.exceptions import ClientError

OUT = pathlib.Path(sys.argv[1])
UTC = datetime.timezone.utc
def now(): return datetime.datetime.now(UTC)
def safe(x):
    if isinstance(x, datetime.datetime): return x.astimezone(UTC).isoformat()
    if isinstance(x, bytes): return {'hex': x.hex()}
    if isinstance(x, dict): return {k:safe(v) for k,v in x.items()}
    if isinstance(x, (list,tuple)): return [safe(v) for v in x]
    return x
name = 'stackd-kinesis-efo-close-' + secrets.token_hex(6)
D = {'schemaVersion':1, 'source':'Native AWS; aws_cli.py STS guard plus boto3 modeled event stream; signed_requests.py inspected, custom signing unnecessary.', 'account':'000000000000', 'region':'us-east-1', 'startedAt':now(), 'sdk':{'boto3':boto3.__version__, 'botocore':botocore.__version__, 'urllib3':urllib3.__version__}, 'calls':[], 'observations':[], 'ownedResources':{'streamName':name,'consumers':[]}, 'metricRechecks':[], 'cleanup':[], 'references':['https://docs.aws.amazon.com/kinesis/latest/APIReference/API_SubscribeToShard.html','https://docs.aws.amazon.com/streams/latest/dev/monitoring-with-cloudwatch.html','https://github.com/boto/botocore/blob/1.43.98/botocore/eventstream.py','https://github.com/urllib3/urllib3/blob/2.8.0/src/urllib3/response.py'], 'method':{'sdkConfig':{'connect_timeout':10,'read_timeout':340,'retries':{'total_max_attempts':1,'mode':'standard'}},'cliEnvironment':{'AWS_REGION':'us-east-1','AWS_DEFAULT_REGION':'us-east-1','AWS_MAX_ATTEMPTS':'1'},'closeMethod':'On the same thread, immediately after the selected fully decoded event yields, call response[EventStream].close(), then close that dedicated boto3 client with client.close(). No socket shutdown monkeypatch, iterator continuation, reconnect, admission retry, or additional SubscribeToShard call for that consumer. Record raw HTTP response, connection and captured socket states on either side.', 'frameTimeMeaning':'Client UTC and monotonic time immediately after SDK yields decoded frame, not service publication timestamp.', 'postCloseVisibility':'Cannot directly observe service frames after client socket closure. Native per-minute metrics can establish continued service-side samples, not packets received by a closed client or exact internal disconnect-detection timing.', 'sourcePaths':['scripts/aws/aws_cli.py','scripts/aws/signed_requests.py','scripts/aws/lambda_streaming_probe.py'], 'probeSource':pathlib.Path(__file__).read_text()}}
def save(): OUT.write_text(json.dumps(safe(D),indent=2)+'\n')
def call(label, client, op, params=None, allow_error=False):
    params = params or {}
    api = client.meta.method_to_api_mapping[op]
    c={'label':label,'service':client.meta.service_model.service_name,'operation':api,'input':safe(params),'startedAt':now()}
    try:
        out=getattr(client,op)(**params)
        c['result']={'code':'Success','output':safe({k:v for k,v in out.items() if k!='EventStream'})}
    except ClientError as e:
        out=e.response
        c['result']={'code':out['Error']['Code'],'output':safe(out)}
        if not allow_error:
            c['finishedAt']=now(); c['requestIds']=[out.get('ResponseMetadata',{}).get('RequestId')]; D['calls'].append(c); save(); raise
    c['finishedAt']=now(); c['requestIds']=[out.get('ResponseMetadata',{}).get('RequestId')]
    c['sequence']=len(D['calls'])+1; D['calls'].append(c); save()
    return out
config=Config(connect_timeout=10,read_timeout=340,retries={'total_max_attempts':1,'mode':'standard'})
env=dict(os.environ,AWS_REGION='us-east-1',AWS_DEFAULT_REGION='us-east-1',AWS_MAX_ATTEMPTS='1')
c={'label':'confirm-approved-caller-cli','service':'sts','operation':'GetCallerIdentity','input':{},'startedAt':now()}
c['result']=aws_cli.observe('sts','get-caller-identity',env=env); c['finishedAt']=now(); c['requestIds']=[]; c['sequence']=1; D['calls'].append(c); save()
assert c['result']['output']['Account']=='000000000000', 'unapproved AWS account'
session=boto3.Session(region_name='us-east-1')
sts=session.client('sts',config=config); k=session.client('kinesis',config=config); cw=session.client('cloudwatch',config=config)
assert call('confirm-approved-caller-sdk',sts,'get_caller_identity')['Account']=='000000000000'
created=False; arn=None

def socket_state(raw,conn,sock):
    state={'recordedAt':now(),'monotonic':time.monotonic(),'rawClosed':raw.closed,'rawIsClosed':raw.isclosed(),'connectionSocketPresent':conn.sock is not None if conn else None,'socketFileno':sock.fileno() if sock else None,'socketClosed':getattr(sock,'_closed',None)}
    if sock and sock.fileno()>=0:
        state.update(localAddress=sock.getsockname(),peerAddress=sock.getpeername(),socketTimeout=sock.gettimeout())
    return state

try:
    call('create-owned-empty-one-shard-stream',k,'create_stream',{'StreamName':name,'ShardCount':1,'StreamModeDetails':{'StreamMode':'PROVISIONED'}}); created=True
    for i in range(60):
        s=call('wait-stream-active-'+str(i),k,'describe_stream_summary',{'StreamName':name})['StreamDescriptionSummary']
        if s['StreamStatus']=='ACTIVE': break
        time.sleep(2)
    else: raise RuntimeError('stream did not activate')
    arn=s['StreamARN']; D['ownedResources']['streamARN']=arn
    shard=call('list-owned-shards',k,'list_shards',{'StreamARN':arn})['Shards'][0]['ShardId']; D['ownedResources']['shardId']=shard
    for label,frames in [('after-initial-frame',1),('after-six-heartbeats',7)]:
        cname=name+'-'+label
        consumer=call('register-'+label,k,'register_stream_consumer',{'StreamARN':arn,'ConsumerName':cname})['Consumer']
        resource={'consumerName':cname,'consumerARN':consumer['ConsumerARN'],'label':label}; D['ownedResources']['consumers'].append(resource); save()
        for i in range(60):
            cstate=call('wait-consumer-'+label+'-'+str(i),k,'describe_stream_consumer',{'ConsumerARN':resource['consumerARN']})['ConsumerDescription']
            if cstate['ConsumerStatus']=='ACTIVE': break
            time.sleep(2)
        else: raise RuntimeError('consumer did not activate')
        client=session.client('kinesis',config=config)
        ob={'label':label,'consumerName':cname,'consumerARN':resource['consumerARN'],'plannedFrameCount':frames,'startedAt':now(),'startedMonotonic':time.monotonic(),'frames':[],'termination':None,'cleanNaturalEOF':False,'exceptions':[],'automaticRetries':0,'reconnects':0}
        D['observations'].append(ob); save()
        resp=call('subscribe-once-'+label,client,'subscribe_to_shard',{'ConsumerARN':resource['consumerARN'],'ShardId':shard,'StartingPosition':{'Type':'LATEST'}})
        stream=resp['EventStream']; raw=stream._raw_stream; conn=raw._connection; sock=conn.sock if conn else None
        ob['headersReceivedAt']=now(); ob['responseMetadata']=safe(resp['ResponseMetadata']); ob['initialTransportState']=socket_state(raw,conn,sock)
        ob['transportTypes']={'eventStream':type(stream).__module__+'.'+type(stream).__name__,'rawStream':type(raw).__module__+'.'+type(raw).__name__,'connection':type(conn).__module__+'.'+type(conn).__name__,'socket':type(sock).__module__+'.'+type(sock).__name__}
        try:
            for frame in stream:
                t=now(); m=time.monotonic(); ob['frames'].append({'receivedAt':t,'secondsSinceSubscribe':m-ob['startedMonotonic'],'monotonic':m,'decoded':safe(frame)}); save()
                if len(ob['frames'])==frames:
                    ob['beforeCloseTransportState']=socket_state(raw,conn,sock)
                    ob['closeCalledAt']=now(); ob['closeCalledMonotonic']=time.monotonic()
                    stream.close()
                    ob['closeReturnedAt']=now(); ob['closeReturnedMonotonic']=time.monotonic()
                    ob['afterCloseTransportState']=socket_state(raw,conn,sock)
                    ob['sessionCloseCalledAt']=now(); ob['sessionCloseCalledMonotonic']=time.monotonic(); client.close()
                    ob['sessionCloseReturnedAt']=now(); ob['sessionCloseReturnedMonotonic']=time.monotonic()
                    ob['afterSessionCloseTransportState']=socket_state(raw,conn,sock)
                    ob['termination']='client-initiated-event-stream-close'; break
            else:
                ob['cleanNaturalEOF']=True; ob['termination']='natural-eof-before-planned-close'; ob['eofAt']=now()
        except Exception as e:
            ob['exceptions'].append({'at':now(),'type':type(e).__name__,'message':str(e)}); ob['termination']='exception'; raise
        finally:
            ob['finishedAt']=now(); ob['secondsUntilFinish']=time.monotonic()-ob['startedMonotonic']; stream.close(); client.close(); save()
        print('CLOSED',label,len(ob['frames']),ob['secondsUntilFinish'],flush=True)
    latest_start=max(x['startedAt'] for x in D['observations'])
    horizon=latest_start+datetime.timedelta(seconds=300)
    window_start=min(x['startedAt'] for x in D['observations']).replace(second=0,microsecond=0)-datetime.timedelta(minutes=1)
    window_end=horizon.replace(second=0,microsecond=0)+datetime.timedelta(minutes=4)
    D['queryWindow']={'start':window_start,'endExclusive':window_end,'periodSeconds':60,'latestOrdinaryFiveMinuteHorizon':horizon,'note':'Fixed whole-minute window spans before both subscriptions through at least three minutes after latest ordinary 300s subscription horizon. No records are written.'}
    # Every resource remains ACTIVE through latest horizon plus 900 seconds.
    targets=[('post-close-60s',max(x['closeReturnedAt'] for x in D['observations'])+datetime.timedelta(seconds=60)),('horizon-plus-0s',horizon),('horizon-plus-120s',horizon+datetime.timedelta(seconds=120)),('horizon-plus-300s',horizon+datetime.timedelta(seconds=300)),('horizon-plus-600s',horizon+datetime.timedelta(seconds=600)),('horizon-plus-900s',horizon+datetime.timedelta(seconds=900))]
    for label,target in targets:
        delay=(target-now()).total_seconds()
        if delay>0: time.sleep(delay)
        check={'label':label,'scheduledAt':target,'startedAt':now(),'secondsAfterLatestOrdinaryHorizon':(now()-horizon).total_seconds()}; D['metricRechecks'].append(check); save()
        call('kept-stream-active-'+label,k,'describe_stream_summary',{'StreamARN':arn})
        for resource in D['ownedResources']['consumers']:
            call('kept-consumer-active-'+resource['label']+'-'+label,k,'describe_stream_consumer',{'ConsumerARN':resource['consumerARN']})
            for metric in ['SubscribeToShardEvent.Success','SubscribeToShardEvent.Bytes','SubscribeToShardEvent.Records','SubscribeToShardEvent.MillisBehindLatest','SubscribeToShard.Success']:
                call('metrics-'+label+'-'+resource['label']+'-'+metric,cw,'get_metric_statistics',{'Namespace':'AWS/Kinesis','MetricName':metric,'Dimensions':[{'Name':'StreamName','Value':name},{'Name':'ConsumerName','Value':resource['consumerName']}],'StartTime':window_start,'EndTime':window_end,'Period':60,'Statistics':['SampleCount','Sum','Minimum','Maximum','Average']})
        check['finishedAt']=now(); save(); print('RECHECK',label,flush=True)
except Exception as e:
    D['fatalError']={'type':type(e).__name__,'message':str(e),'at':now()}; save(); raise
finally:
    for resource in D['ownedResources']['consumers']:
        r=call('cleanup-deregister-'+resource['label'],k,'deregister_stream_consumer',{'ConsumerARN':resource['consumerARN']},True)
        for i in range(60):
            r=call('prove-consumer-absent-'+resource['label']+'-'+str(i),k,'describe_stream_consumer',{'ConsumerARN':resource['consumerARN']},True)
            if r.get('Error',{}).get('Code')=='ResourceNotFoundException':
                D['cleanup'].append({'resource':resource['consumerARN'],'absenceProvenBy':'DescribeStreamConsumer','at':now(),'code':'ResourceNotFoundException'}); break
            time.sleep(2)
    if created:
        call('cleanup-delete-owned-stream',k,'delete_stream',{'StreamName':name,'EnforceConsumerDeletion':True},True)
        for i in range(90):
            r=call('prove-stream-absent-'+str(i),k,'describe_stream_summary',{'StreamName':name},True)
            if r.get('Error',{}).get('Code')=='ResourceNotFoundException':
                D['cleanup'].append({'resource':arn or name,'absenceProvenBy':'DescribeStreamSummary','at':now(),'code':'ResourceNotFoundException'}); break
            time.sleep(2)
    D['finishedAt']=now(); save(); sts.close(); k.close(); cw.close()
    print('FINISHED',len(D['cleanup']),str(OUT),flush=True)
